631				<article class="card">
632					<h3>Interactive Counter</h3>
633					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
634					<div class="counter">
635						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
636						<output id="count" aria-live="off">0</output>
637						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
638						<button id="reset" type="button" aria-label="Reset count to zero">Reset</button>
639					</div>
640					<div class="live-region" aria-live="polite" aria-atomic="true">
641						<span id="count-message"></span>
642					</div>
643				</article>
644			</section>
