705		<script>
706			const themeToggle = document.getElementById('theme-toggle');
707			const htmlElement = document.documentElement;
708			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
709	
710			const themeColors = { light: '#ffffff', dark: '#121212' };
711			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
712			themeColorMetas.forEach((meta) => {
713				meta.dataset.defaultContent = meta.content;
714			});
715	
716			const updateThemeUI = () => {
717				const forced = htmlElement.dataset.theme;
718				const isDark = forced ? forced === 'dark' : prefersDark.matches;
719				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
720				themeToggle.textContent = isDark ? '☀️' : '🌙';
721				themeToggle.setAttribute('aria-label', label);
722				themeToggle.title = label;
