735					const next = current === 'dark' ? 'light' : 'dark';
736					// Choosing the system theme clears the override so the page follows the OS again.
737					try {
738						if (next === systemTheme) {
739							delete htmlElement.dataset.theme;
740							localStorage.removeItem('theme');
741						} else {
742							htmlElement.dataset.theme = next;
743							localStorage.setItem('theme', next);
744						}
745					} catch {}
746					updateThemeUI();
747				});
748	
749				prefersDark.addEventListener('change', () => {
750					if (!htmlElement.dataset.theme) {
751						updateThemeUI();
752					}
753				});
754			}
755	
756			const copyrightYear = document.getElementById('copyright-year');
757			if (copyrightYear) {
758				copyrightYear.textContent = String(new Date().getFullYear());
759			}
760	
761			const messages = [
762				"This update was announced to screen readers!",
763				"Dynamic content updates work with aria-live regions.",
