765				"Try this with a screen reader like NVDA or JAWS!"
766			];
767			let nextMessage = 0;
768			let count = 0;
769			const announceBtn = document.getElementById('announce');
770			const liveMessage = document.getElementById('live-message');
771			const contactForm = document.getElementById('contact-form');
772			const emailInput = document.getElementById('email');
773			const messageInput = document.getElementById('message');
774			const messageCount = document.getElementById('message-count');
775			const formStatus = document.getElementById('form-status');
776			const countDisplay = document.getElementById('count');
777			const countMessage = document.getElementById('count-message');
778			const decreaseBtn = document.getElementById('decrease');
779			const increaseBtn = document.getElementById('increase');
780			const resetBtn = document.getElementById('reset');
781	
782			const updateCountDisplay = () => {
783				countDisplay.textContent = String(count);
784				countMessage.textContent = `Count is ${count}.`;
785			};
786	
787			if (countDisplay && countMessage) {
788				decreaseBtn?.addEventListener('click', () => {
789					count--;
790					updateCountDisplay();
791				});
792	
793				increaseBtn?.addEventListener('click', () => {
794					count++;
795					updateCountDisplay();
796				});
797	
798				resetBtn?.addEventListener('click', () => {
799					count = 0;
800					updateCountDisplay();
801				});
802			}
803	
804			if (announceBtn && liveMessage) {
805				announceBtn.addEventListener('click', () => {
806					liveMessage.textContent = messages[nextMessage];
807					nextMessage = (nextMessage + 1) % messages.length;
808				});
809			}
810	
811			if (contactForm) {
812				const emailError = document.getElementById('email-error');
813	
814				const updateMessageCount = () => {
815					if (messageInput && messageCount) {
816						const remaining = messageInput.maxLength - messageInput.value.length;
817						messageCount.textContent = remaining.toLocaleString();
818					}
819				};
820	
821				messageInput?.addEventListener('input', updateMessageCount);
822				// Browsers may restore field values on back/forward navigation.
823				window.addEventListener('pageshow', updateMessageCount);
824				updateMessageCount();
825	
826				const setEmailError = (message) => {
827					emailError.textContent = message;
828					if (message) {
829						emailInput.setAttribute('aria-invalid', 'true');
830						emailInput.setAttribute('aria-describedby', 'email-error email-help');
831					} else {
832						emailInput.removeAttribute('aria-invalid');
833						emailInput.setAttribute('aria-describedby', 'email-help');
834					}
835				};
836	
837				const validateEmail = () => {
838					let message = '';
839					if (emailInput.validity.valueMissing) {
840						message = 'Enter your email address.';
841					} else if (!emailInput.validity.valid) {
842						message = 'Enter an email address in the format name@example.com.';
843					}
844					setEmailError(message);
845					return !message;
846				};
847	
848				emailInput.addEventListener('blur', () => {
849					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
850						validateEmail();
851					}
852				});
853	
854				emailInput.addEventListener('input', () => {
855					if (emailInput.hasAttribute('aria-invalid')) {
856						validateEmail();
857					}
858				});
859	
860				contactForm.addEventListener('input', () => {
861					formStatus.textContent = '';
862				});
863	
864				contactForm.addEventListener('submit', async (event) => {
865					event.preventDefault();
866					const submitBtn = contactForm.querySelector('button[type="submit"]');
867					if (submitBtn.getAttribute('aria-disabled') === 'true') {
868						return;
869					}
870					formStatus.textContent = '';
871					if (!validateEmail()) {
872						emailInput.focus();
873						return;
874					}
875					const originalText = submitBtn.textContent;
876					// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
877					submitBtn.setAttribute('aria-disabled', 'true');
878					submitBtn.setAttribute('aria-busy', 'true');
879					submitBtn.textContent = 'Sending…';
880					formStatus.textContent = 'Sending your message…';
881					await new Promise(resolve => setTimeout(resolve, 800));
882					contactForm.reset();
883					setEmailError('');
884					updateMessageCount();
885					submitBtn.removeAttribute('aria-disabled');
886					submitBtn.removeAttribute('aria-busy');
887					submitBtn.textContent = originalText;
888					formStatus.textContent = "Thanks! This is a demo, so nothing was sent.";
889					emailInput.focus();
890				});
891			}
892		</script>
893	</body>
