				if (messageInput && messageCount) {
					const remaining = messageInput.maxLength - messageInput.value.length;
					// Match the page language rather than the browser locale.
					messageCount.textContent = remaining.toLocaleString(htmlElement.lang);
				}
			};

			messageInput?.addEventListener('input', updateMessageCount);
			// Browsers may restore field values on back/forward navigation.
			window.addEventListener('pageshow', updateMessageCount);
			updateMessageCount();

			const setEmailError = (message) => {
				emailError.textContent = message;
				if (message) {
					emailInput.setAttribute('aria-invalid', 'true');
					emailInput.setAttribute('aria-describedby', 'email-error email-help');
				} else {
					emailInput.removeAttribute('aria-invalid');
					emailInput.setAttribute('aria-describedby', 'email-help');
				}
			};

			const validateEmail = () => {
				let message = '';
				if (emailInput.validity.valueMissing) {
					message = 'Enter your email address.';
				} else if (!emailInput.validity.valid) {
					message = 'Enter an email address in the format name@example.com.';
				}
				setEmailError(message);
				return !message;
			};

			emailInput.addEventListener('blur', () => {
				if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
					validateEmail();
				}
			});

			emailInput.addEventListener('input', () => {
				if (emailInput.hasAttribute('aria-invalid')) {
					validateEmail();
				}
			});

			contactForm.addEventListener('input', () => {
				if (!isSending()) {
					setFormStatus('');
				}
			});

			contactForm.addEventListener('submit', async (event) => {
				event.preventDefault();
				if (isSending()) {
					return;
				}
				setFormStatus('');
				if (!validateEmail()) {
					emailInput.focus();
					return;
				}
				const originalText = submitBtn.textContent;
				// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
				submitBtn.setAttribute('aria-disabled', 'true');
				submitBtn.setAttribute('aria-busy', 'true');
				submitBtn.textContent = 'Sending…';
				setFormStatus('Sending your message…', 'pending');
				// Read-only rather than disabled so the fields stay focusable while sending.
				emailInput.readOnly = true;
				messageInput.readOnly = true;
				await new Promise(resolve => setTimeout(resolve, 800));
				emailInput.readOnly = false;
				messageInput.readOnly = false;
				contactForm.reset();
				setEmailError('');
				updateMessageCount();
				submitBtn.removeAttribute('aria-disabled');
				submitBtn.removeAttribute('aria-busy');
				submitBtn.textContent = originalText;
				setFormStatus("Thanks! This is a demo, so nothing was sent.");
				emailInput.focus();
			});
		}
	</script>
</body>
